"""Temperature conversion."""


def celsius_to_fahrenheit(c):
    if not isinstance(c, (int, float)) or isinstance(c, bool):
        raise TypeError("Input must be an int or float.")
    if c < -273.15:
        raise ValueError("Temperature cannot be below absolute zero (-273.15 °C).")
    return c * 9 / 5 + 32

from temperature import celsius_to_fahrenheit

# Test valid inputs
print(f"0C = {celsius_to_fahrenheit(0)}F")
print(f"100C = {celsius_to_fahrenheit(100)}F")
print(f"-273.15C = {celsius_to_fahrenheit(-273.15)}F")

# Test invalid types
try:
    celsius_to_fahrenheit("0")
except TypeError as e:
    print(f"Caught expected TypeError: {e}")

try:
    celsius_to_fahrenheit(True)
except TypeError as e:
    print(f"Caught expected TypeError (bool): {e}")

# Test invalid values
try:
    celsius_to_fahrenheit(-273.16)
except ValueError as e:
    print(f"Caught expected ValueError: {e}")

